DO $$ BEGIN IF EXISTS(SELECT FROM public.leyes WHERE siglas='PODECOBI-LINEAMIENTOS-M1' OR id='0cc61fa0-26bd-5551-a4c2-aeb56b84964b') THEN RAISE EXCEPTION 'Instrumento ya registrado'; END IF; END $$;
INSERT INTO public.leyes (id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave) VALUES ('0cc61fa0-26bd-5551-a4c2-aeb56b84964b', 'PODECOBI-LINEAMIENTOS-M1', 'ACUERDO por el que se modifica el diverso por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar.', 'acuerdo', '2025-08-29', 'https://sidof.segob.gob.mx/notas/docFuente/5766905', ARRAY['PODECOBI','Polos de Desarrollo Económico para el Bienestar']);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('a1ffbe5b-d195-5e9a-9677-d7e02789a231', '0cc61fa0-26bd-5551-a4c2-aeb56b84964b', 1, 'Preámbulo y considerandos', '<p>ACUERDO por el que se modifica el diverso por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar.</p>
<p>Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Secretaría de Economía.</p>
<p>El Comité Intersecretarial de Promoción, con fundamento en los artículos 25 y 26 de la Constitución Política de los Estados Unidos Mexicanos; 14, 31, 32 Bis, 33, 34, 38, 41 y 42 Ter de la Ley Orgánica de la Administración Pública Federal; Primero, párrafo segundo, Décimo, Décimo Primero, Décimo Segundo y Transitorio segundo del "Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar", publicado en el Diario Oficial de la Federación el 22 de mayo de 2025 y su posterior modificación; así como en el lineamiento 4, fracción I, del Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, publicado el 22 de mayo de 2025 en el mismo órgano de difusión oficial, y</p>
<p>CONSIDERANDO</p>
<p>Que el artículo 25, primer párrafo, de la Constitución Política de los Estados Unidos Mexicanos (CPEUM), ordena que corresponde al Estado la rectoría del desarrollo nacional para garantizar que este sea integral y sustentable, que fortalezca la Soberanía de la Nación y su régimen democrático; asimismo, que, mediante la competitividad, fomento del crecimiento económico y el empleo, así como una más justa distribución del ingreso y la riqueza, se permita el pleno ejercicio de la libertad y la dignidad de los individuos, grupos y clases sociales, cuya seguridad protege la Constitución;</p>
<p>Que el artículo 26, apartado A, de la CPEUM establece que el Estado organizará un sistema de planeación democrático del desarrollo nacional que imprima solidez, dinamismo, competitividad, permanencia y equidad al crecimiento de la economía;</p>
<p>Que el Plan Nacional de Desarrollo 2025-2030, publicado en el Diario Oficial de la Federación (DOF) el 15 de abril de 2025, contiene en su Eje General 2, el Objetivo 2.1: Fortalecer la red de protección social para garantizar la inclusión social y económica de toda la población, con especial atención a los grupos en situación de vulnerabilidad;</p>
<p>Que el "Plan México", es contemplado por el Plan Nacional de Desarrollo 2025-2030, como una herramienta de visión a largo plazo que permitirá a la economía nacional dejar de depender de proveedurías extranjeras, respecto de productos que desde hace tiempo el país ya produce con alta calidad;</p>
<p>Que en la estrategia prevista en el numeral 7 de las Estrategias del Plan México, previstas en el Plan Nacional de Desarrollo 2025-2030, se establece el "Promover los polos de desarrollo y de bienestar a partir de vocaciones regionales";</p>
<p>Que, con fecha 22 de mayo de 2025, se publicó en el DOF el Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar, y su modificación publicada en el mismo medio de difusión el 31 de julio de 2025, señala, en su artículo Décimo, que para el establecimiento de los Polos de Desarrollo Económico para el Bienestar se crea el Comité Intersecretarial de Promoción, integrado por una persona representante de la Secretaría de Economía quien presidirá dicho comité, y por una persona representante de las secretarías de Hacienda y Crédito Público, de Desarrollo Agrario, Territorial y Urbano, de Energía y de Medio Ambiente y Recursos Naturales y de la Agencia de Transformación Digital y Telecomunicaciones, y como invitados permanentes a los representantes de la Secretaría de Educación Pública, de la Comisión Federal de Electricidad, de la Comisión Nacional del Agua y del Consejo Asesor de Desarrollo Económico Regional y Relocalización;</p>
<p>Que, de igual forma, en el artículo Décimo del Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar, se confiere la facultad al Comité Intersecretarial de Promoción para emitir los lineamientos en los que establecerá, entre otros, su integración, atribuciones, quorum, desarrollo de sesiones, criterios de selección que deben cumplir las propuestas de superficies de terrenos, así como las convocatorias de los concursos que lleven a cabo las entidades federativas;</p>
<p>Que, con fecha 22 de mayo de 2025, se publicó en el DOF, el Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, mismo que, en su lineamiento 4, fracción I, faculta al Comité Intersecretarial de Promoción para aprobar las modificaciones a dichos Lineamientos;</p>
<p>Que, con fecha 31 de julio de 2025, se publicó en el DOF el Decreto por el que se modifica el diverso por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar;</p>
<p>Que, en consecuencia, resulta necesario modificar los lineamientos a las disposiciones previstas en dicho ordenamiento, así como incorporar diversas propuestas de los integrantes del Comité Intersecretarial de Promoción;</p>
<p>Que, con fecha 13 de agosto de 2025, en la Segunda Sesión Extraordinaria del Comité Intersecretarial de Promoción, se aprobaron las modificaciones a los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, una vez que se recibieron las observaciones de los integrantes; por lo que hemos tenido a bien emitir el siguiente:</p>', 'preambulo', 'PODECOBI-LINEAMIENTOS-M1', 'Acuerdo modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('bf142179-a3b3-51dc-a7ee-2c3a3c4550aa', '0cc61fa0-26bd-5551-a4c2-aeb56b84964b', 2, 'Artículo Único', '<p>ACUERDO POR EL QUE SE MODIFICA EL DIVERSO POR EL QUE SE EMITEN LOS LINEAMIENTOS PARA LOS POLOS DE DESARROLLO ECONÓMICO PARA EL BIENESTAR</p>
<p>ARTÍCULO ÚNICO.- Se reforman los lineamientos 1, 2, fracciones III y XV, 4, fracción V, 8, fracción I, 11, fracción VI, 15, fracciones II, III, V, VI y IX, 16, fracciones II y III, 26, párrafo primero y 33, párrafo segundo; y se adicionan a los lineamientos 2, las fracciones I Bis, XI Bis, XXI Bis y XXVI, 3, al párrafo primero la fracción VI, y al segundo párrafo la fracción IV, 4, fracción XI Bis, 6, fracción VI Bis, 8, fracción XI, así como un Capítulo Séptimo Bis, con sus lineamientos 38 Bis, 38 Ter, 38 Quater, 38 Quinquies y 38 Sexies, al Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, publicado en el Diario Oficial de la Federación el 22 de mayo de 2025, para quedar como sigue:</p>', 'ordinario', 'PODECOBI-LINEAMIENTOS-M1', 'Acuerdo modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('7e598541-2c0f-5472-86ba-5df9953b8211', '0cc61fa0-26bd-5551-a4c2-aeb56b84964b', 3, 'Lineamiento 1', '<p>"CAPÍTULO PRIMERO</p>
<p>GENERALIDADES</p>
<p>1. Los presentes Lineamientos tienen por objeto establecer la integración, atribuciones, quorum, desarrollo de sesiones, decisiones y demás aspectos relativos al Comité Intersecretarial de Promoción señalado en el artículo Décimo del Decreto por el que se otorgan estímulos en los Polos de Desarrollo Económico para el Bienestar; los criterios de selección que deben cumplir los Polos de Desarrollo Económico para el Bienestar; la regulación para la celebración de los Convenios de Coordinación y de facilitación de trámites administrativos entre el Gobierno Federal, las Entidades Federativas, y en su caso, los Municipios en los que su ubiquen los citados Polos; los elementos que debe tener el Vehículo de Propósito Especial que establezcan las Entidades Federativas para la regulación de los mencionados Polos; así como los requisitos que deben cumplir las personas morales que estén interesadas en obtener la Autorización para ser Desarrolladores, a que se refieren los artículos Primero y Décimo Primero del Decreto; los requisitos que integrarán las convocatorias públicas que se emitan para el efecto, así como el procedimiento para realizar los concursos públicos o asignaciones; las causales y el procedimiento de revocación de la Autorización.</p>', 'ordinario', 'PODECOBI-LINEAMIENTOS-M1', 'Acuerdo modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('1443812b-cd74-5d0e-af22-3613537cb139', '0cc61fa0-26bd-5551-a4c2-aeb56b84964b', 4, 'Lineamiento 2', '<p>2. ...</p>
<p>I. ...</p>
<p>I Bis. ATDT: Agencia de Transformación Digital y Telecomunicaciones.</p>
<p>II. ...</p>
<p>III. Autorización: Acto jurídico mediante el cual la Entidad Federativa autoriza a los Desarrolladores para construir, desarrollar y administrar un Polo de Desarrollo Económico para el Bienestar.</p>
<p>IV. a XI. ...</p>
<p>XI Bis. Convenio de facilitación: Instrumento jurídico celebrado entre el Comité Intersecretarial de Promoción, las Entidades Federativas y los Municipios en los que se ubiquen los Polos de Desarrollo Económico para el Bienestar, en el ámbito de su competencia, con el fin de establecer el compromiso de la facilitación y agilización de los trámites y las gestiones administrativas correspondientes para la instalación y operación de los referidos Polos.</p>
<p>XII. a XIV. ...</p>
<p>XV. Decreto: Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar, publicado en el Diario Oficial de la Federación el 22 de mayo de 2025 y su posterior modificación.</p>
<p>XVI. a XXI. ...</p>
<p>XXI Bis. SEP: Secretaría de Educación Pública.</p>
<p>XXII. a XXV. ...</p>
<p>XXVI. Ventanilla: Ventanilla de recepción de las solicitudes de trámites y las gestiones que las personas físicas y morales interesadas en realizar actividades económicas productivas al interior de los Polos de Desarrollo Económico para el Bienestar y los Desarrolladores, deben cumplir de manera obligatoria o diferida, ubicada en calle Pachuca 189, colonia Condesa, D.T. Cuauhtémoc, C.P. 06140 Ciudad de México. También se considera como Ventanilla la dirección de correo electrónico polosdedesarrollo@economia.gob.mx.</p>', 'ordinario', 'PODECOBI-LINEAMIENTOS-M1', 'Acuerdo modificatorio', NULL);
INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('5f455001-2d8e-5339-8b34-b3c362f85c9e', '0cc61fa0-26bd-5551-a4c2-aeb56b84964b', 5, 'Lineamiento 3', '<p>CAPÍTULO SEGUNDO</p>
